INSERT INTO ruta (codigo, nombre, origen, destino, tiempo_estimado_min, estado, color_hex, descripcion, accesible_movilidad_reducida, observaciones_accesibilidad, hora_aproximada, verificada) SELECT 'RUT-CAMP-SOC-BCG-CG', 'Campestre - El Socorro - Bocagrande / Castillogrande', 'El Rodeo', 'Castillogrande', NULL, 'ACTIVA', '#1f77b4', 'DATOS PROVISIONALES. No publicar ni usar como recorrido vigente hasta validar. Operador reportado: Coointracar Ltda. (operador reportado; vigencia pendiente de validar). Fuente: Descripción transcrita del documento compartido. Menciona los decretos 2124 y 2127 de octubre de 2025, cuyo texto y vigencia no se verificaron. El retorno se describe en sentido contrario, sujeto al trazado autorizado. Horarios y coordenadas exactas no informados.', 0, NULL, NULL, 0 WHERE NOT EXISTS (SELECT 1 FROM ruta WHERE codigo = 'RUT-CAMP-SOC-BCG-CG');
INSERT INTO ruta (codigo, nombre, origen, destino, tiempo_estimado_min, estado, color_hex, descripcion, accesible_movilidad_reducida, observaciones_accesibilidad, hora_aproximada, verificada) SELECT 'RUT-POZ-TORICES', 'El Pozón - Villagrande - Socorro - Centro - Torices', 'El Pozón', 'Torices', NULL, 'ACTIVA', '#ff7f0e', 'DATOS PROVISIONALES. No publicar ni usar como recorrido vigente hasta validar. Operador reportado: Coointracar Ltda. (operador reportado; pendiente de confirmar). Fuente: Recorrido transcrito del documento compartido; hace falta localizar y verificar el acto administrativo o ficha oficial de esta ruta. El orden de vuelta se generó invirtiendo la ida y debe validarse.', 0, NULL, NULL, 0 WHERE NOT EXISTS (SELECT 1 FROM ruta WHERE codigo = 'RUT-POZ-TORICES');
INSERT INTO ruta (codigo, nombre, origen, destino, tiempo_estimado_min, estado, color_hex, descripcion, accesible_movilidad_reducida, observaciones_accesibilidad, hora_aproximada, verificada) SELECT 'RUT-37-SIM-CENTRO', 'Ruta 37 - Simón Bolívar - San Fernando - Socorro - Centro', 'Simón Bolívar', 'Centro', NULL, 'ACTIVA', '#2ca02c', 'DATOS PROVISIONALES. No publicar ni usar como recorrido vigente hasta validar. Operador reportado: Transporte público colectivo (operador no confirmado). Fuente: Recorrido reportado en el documento compartido. Fuentes distritales citadas: https://mejoranormativa.cartagena.gov.co/normativa/memoria-justificativa-proyectos-normativos/memoria-justificativa-ruta-37-311 y https://mejoranormativa.cartagena.gov.co/normativa/analisis-impacto-normativo/analisis-impacto-normativo-modificacion-del-recorrido-ruta-37-312. Cotejar el trazado y el sentido con los anexos técnicos antes de publicarlo. El orden de vuelta se generó invirtiendo la ida y debe validarse.', 0, NULL, NULL, 0 WHERE NOT EXISTS (SELECT 1 FROM ruta WHERE codigo = 'RUT-37-SIM-CENTRO');
INSERT INTO ruta (codigo, nombre, origen, destino, tiempo_estimado_min, estado, color_hex, descripcion, accesible_movilidad_reducida, observaciones_accesibilidad, hora_aproximada, verificada) SELECT 'RUT-30A-NB-CENTRO', 'Ruta 30A - Nuevo Bosque - Calamares - Centro', 'Terminal / Nuevo Bosque', 'Centro', NULL, 'ACTIVA', '#9467bd', 'DATOS PROVISIONALES. No publicar ni usar como recorrido vigente hasta validar. Operador reportado: Cootransurb Ltda. (operador reportado; pendiente de confirmar). Fuente: Recorrido resumido en el documento compartido. Índice distrital citado: https://mejoranormativa.cartagena.gov.co/normativa/proyectos-especificos-regulacion. La publicación sobre modificación de la Ruta 30A de septiembre de 2025 incluye un documento técnico; verificar los puntos exactos de inicio y el trazado. Horarios y coordenadas exactas no informados.', 0, NULL, NULL, 0 WHERE NOT EXISTS (SELECT 1 FROM ruta WHERE codigo = 'RUT-30A-NB-CENTRO');
